package com.example.leetcodetrainer.coaching.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="coaching_messages") public class CoachingMessage {
 @Id private UUID id; @Column(name="attempt_id",nullable=false) private UUID attemptId; @Column(nullable=false) private String provider; @Column(name="provider_version",nullable=false) private String providerVersion; @Lob @Column(nullable=false) private String observation; @Lob @Column(nullable=false) private String bottleneck; @Lob @Column(nullable=false) private String interpretation; @Lob @Column(name="next_test",nullable=false) private String nextTest; @Lob @Column(nullable=false) private String evidence; @Lob private String emotionalAcknowledgement; @Lob private String safetyNote; @Lob @Column(nullable=false) private String renderedMessage; @Column(nullable=false) private Instant generatedAt;
 protected CoachingMessage(){} public CoachingMessage(UUID id,UUID attemptId,String provider,String version,CoachingResponse r,Instant now){this.id=id;this.attemptId=attemptId;this.provider=provider;this.providerVersion=version;observation=r.observation();bottleneck=r.bottleneck();interpretation=r.interpretation();nextTest=r.nextTest();evidence=r.evidence();emotionalAcknowledgement=r.emotionalAcknowledgement();safetyNote=r.safetyNote();renderedMessage="観察: "+observation+"\n\nボトルネック: "+bottleneck+"\n\n解釈: "+interpretation+"\n\n次回の検証: "+nextTest+"\n\n根拠: "+evidence;generatedAt=now;}
 public String getObservation(){return observation;} public String getBottleneck(){return bottleneck;} public String getInterpretation(){return interpretation;} public String getNextTest(){return nextTest;} public String getEvidence(){return evidence;} public String getEmotionalAcknowledgement(){return emotionalAcknowledgement;} public String getSafetyNote(){return safetyNote;} public String getProvider(){return provider;} public String getProviderVersion(){return providerVersion;}
}
